// DiskCache stores tarballs under
//   <root>/<namespace>/<name>/<provider>/<version>.tar.gz
// Writes are atomic via a temp file + rename.
type DiskCache struct {
	root string
}

// NewDiskCache creates the root directory if it does not exist.
func NewDiskCache(root string) (*DiskCache, error) {
	if err := os.MkdirAll(root, 0o755); err != nil {
		return nil, fmt.Errorf("mkdir cache root: %w", err)
	}
	return &DiskCache{root: root}, nil
}

func (c *DiskCache) path(m api.Module) string {
	return filepath.Join(c.root, m.Namespace, m.Name, m.Provider, m.Version+".tar.gz")
}

func (c *DiskCache) Get(m api.Module) ([]byte, bool, error) {
	b, err := os.ReadFile(c.path(m))
	if errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, fmt.Errorf("read cache: %w", err)
	}
	return b, true, nil
}

func (c *DiskCache) Put(m api.Module, body []byte) error {
	final := c.path(m)
	if err := os.MkdirAll(filepath.Dir(final), 0o755); err != nil {
		return fmt.Errorf("mkdir cache dir: %w", err)
	}
	tmp, err := os.CreateTemp(filepath.Dir(final), ".birdseye-*.tmp")
	if err != nil {
		return fmt.Errorf("create temp: %w", err)
	}
	tmpName := tmp.Name()
	if _, err := tmp.Write(body); err != nil {
		_ = tmp.Close()
		_ = os.Remove(tmpName)
		return fmt.Errorf("write temp: %w", err)
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(tmpName)
		return fmt.Errorf("close temp: %w", err)
	}
	if err := os.Rename(tmpName, final); err != nil {
		_ = os.Remove(tmpName)
		return fmt.Errorf("rename: %w", err)
	}
	return nil
}
```

