6	import (
7		"sync"
8	
9		"github.com/immuta/operations/services/crow/pkg/api"
10	)
11	
12	// Cache is the storage seam used by Registry. Production uses DiskCache;
13	// tests inject MemCache.
14	type Cache interface {
15		Get(api.Module) ([]byte, bool, error)
16		Put(api.Module, []byte) error
17	}
18	
19	// MemCache is a thread-safe in-memory Cache implementation.
20	type MemCache struct {
21		mu    sync.RWMutex
22		items map[string][]byte
23	}
24	
25	// NewMemCache returns an empty MemCache.
26	func NewMemCache() *MemCache {
27		return &MemCache{items: make(map[string][]byte)}
28	}
29	
30	func memKey(m api.Module) string {
31		return m.Namespace + "/" + m.Name + "/" + m.Provider + "/" + m.Version
32	}
33	
34	func (c *MemCache) Get(m api.Module) ([]byte, bool, error) {
35		c.mu.RLock()
36		defer c.mu.RUnlock()
37		b, ok := c.items[memKey(m)]
38		if !ok {
39			return nil, false, nil
40		}
41		return b, true, nil
42	}
43	
44	func (c *MemCache) Put(m api.Module, body []byte) error {
45		c.mu.Lock()
46		defer c.mu.Unlock()
47		c.items[memKey(m)] = body
48		return nil
49	}
